database_raw.ascii:
$c wff |- ( ) -> /\ \/ $.
$v ph ps ch $.
wph $f wff ph $.
wps $f wff ps $.
wch $f wff ch $.
${
syl.1 $e |- ( ph -> ps ) $.
syl.2 $e |- ( ps -> ch ) $.
syl $p |- ( ph -> ch ) $= wph $.
$}
${
wa $a wff ( ph /\ ps ) $.
$}
${
simpr $p |- ( ( ph /\ ps ) -> ps ) $= wph $.
$}
${
jca.1 $e |- ( ph -> ps ) $.
jca.2 $e |- ( ph -> ch ) $.
jca $p |- ( ph -> ( ps /\ ch ) ) $= wph $.
$}
${
jaoi.1 $e |- ( ph -> ps ) $.
jaoi.2 $e |- ( ch -> ps ) $.
jaoi $p |- ( ( ph \/ ch ) -> ps ) $= wph $.
$}
${
typed-admitted-0.h0 $e |- ( ph -> ps ) $.
typed-admitted-0.h1 $e |- ( ps -> ch ) $.
typed-admitted-0 $p |- ( ph -> ( ps /\ ch ) ) $= wph wps wch typed-admitted-0.h0 wph wps wch typed-admitted-0.h0 typed-admitted-0.h1 syl jca $.
$}

${
native-hole-source-v1.h0 $e |- ( ps -> ch ) $.
native-hole-source-v1 $p |- ( ( ph /\ ps ) -> ch ) $= wph wps wa wps wch wa wch wph wps wa wps wch wph wps simpr wph wps wa wps wch wph wps simpr native-hole-source-v1.h0 syl jca wps wch simpr syl $.
$}

